// 原Encounter安装与Travel实际截停的同捕获来源；不替永久货史或完整World。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_contact_source.hpp"
#include "resident/storage/common_codec.hpp"
#include <limits>
namespace {
// 复用原真实路线，先取几何命中，再原step真正付费落点。
ContactHit paid_contact(Fixture& f,bool terrain_mode){f.catalog.road_encounters=true;
 if(terrain_mode){terrain::TerrainMap map;map.id="map";map.width=40;map.height=20;map.cell_size=20;map.cells.resize(2);map.budgets={{terrain::Mode::foot,100},{terrain::Mode::army,100},{terrain::Mode::boat,100}};map.money_per_tick=7;map.fatigue_per_tick=2;require(terrain::validate_map(map).ok,"actual contact map");f.catalog.world_map_id=map.id;f.catalog.maps.insert(map.id,map);f.catalog.settlements.find("A")->map_xy={10,10};f.catalog.settlements.find("B")->map_xy={30,10};}
 auto other=f.begin("other","A");if(!terrain_mode){require(step_travel(f.common,f.travel,f.catalog,f.services,other).ok,"actual other first road step");++f.common.state().identity.tick;}
 auto carrier=f.begin("carrier","B");auto batch=detect_travel_contacts(f.common,f.travel,f.catalog,f.services,19);require(batch.ok&&batch.value.ordered_hits.size()==1,"actual selected contact hit");
 require(step_travel(f.common,f.travel,f.catalog,f.services,carrier).ok,"carrier actual paid contact step");require(step_travel(f.common,f.travel,f.catalog,f.services,other).ok,"other actual paid contact step");return batch.value.ordered_hits.front();
}
// 沿原phase构造字段，callback随后单独绑定；不把任意字符串当原命中授权。
EncounterInstall installation(const ContactHit& h){EncounterInstall out;out.leaders={h.a,h.b};if(h.road){out.action_ids={h.road->first.trace.action_id,h.road->second.trace.action_id};out.anchors={h.road->first.anchor,h.road->second.anchor};out.resume_paused={h.road->first.trace.params.paused,h.road->second.trace.params.paused};for(auto& order:out.anchor_field_orders)order={"kind","edge_id","origin","progress"};out.anchors_order={h.a,h.b};if(out.action_ids[0]>out.action_ids[1])std::swap(out.anchors_order[0],out.anchors_order[1]);}else{out.action_ids={h.first.trace.action_id,h.second.trace.action_id};out.anchors={h.first.anchor,h.second.anchor};out.resume_paused={h.first.trace.params.paused,h.second.trace.params.paused};}return out;}
// 记录不存在的callback阶段必须拒；安装成功后精确原表、原snapshot与实际钟界才给源。
void actual_contact(bool terrain_mode,bool interactive){Fixture f;const auto h=paid_contact(f,terrain_mode);if(!interactive){f.person("observer","A");f.common.state().metadata.player_actor_id="observer";}InteractionState state;auto op=installation(h);std::optional<TravelContactTruncationDraft> draft;PrivateShopTravelContactBoundary boundary;std::vector<StableId> retained;bool premature_rejected=false;
 op.apply_motion=[&](const StableId& id,bool active){auto moved=apply_contact_truncation(f.common,f.travel,h,id,active,&draft);if(!moved.ok)return moved;premature_rejected=!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft).ok;retained.push_back(id);return common_success();};
 require(f.common.begin_resource_execution_capture().ok,"contact actual capture");auto before=capture_private_shop_travel_contact_boundary(f.common,f.travel,state,h,op);require(before.ok,"contact original boundary");boundary=before.value;const auto next=f.common.state().next_instance_id;const auto carrier=f.funds("carrier"),other=f.funds("other");auto installed=install_encounter(f.common,state,f.common.state().metadata.player_actor_id,op,retained);require(installed.ok&&draft.has_value(),"actual Encounter installed after motion");check(premature_rejected,"callback cannot read not-yet-inserted record");auto source=read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft);require(source.ok,"actual post-install contact source");check(source.value.actual_encounter.created_tick==f.common.tick()+1&&source.value.actual_truncation.source_tick==f.common.tick(),"real from and to retained separately");check(source.value.actual_encounter.status==(interactive?"pending":"resolved")&&source.value.actual_encounter.resolved_tick==(interactive?-1:f.common.tick()+1),"exact interactive terminal shape");check(f.common.state().next_instance_id==next+(interactive?1:2)&&f.common.resource_execution_drafts().empty()&&carrier==f.funds("carrier")&&other==f.funds("other"),"contact has no second fee or refund");
 auto bad=*draft;bad.source_tick++;check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,bad).ok,"motion to cannot replace from");bad=*draft;bad.original_hit.time_num++;check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,bad).ok,"selected geometry cannot be replaced");bad=*draft;bad.before[0].action.remaining_ticks++;check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,bad).ok,"paid precontact actual action retained");bad=*draft;bad.interactive=!interactive;check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,bad).ok,"actual participants choose interaction");
 auto original=state.encounters.front();state.encounters.front().created_tick--;check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft).ok,"record uses actual to");state.encounters.front()=original;state.encounters.front().participants.push_back("invented");check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft).ok,"participants cannot be invented");state.encounters.front()=original;state.encounters.push_back(original);check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft).ok,"duplicate real encounter source refused");state.encounters.pop_back();
 require(f.common.finish_resource_execution_capture().ok,"finish original contact capture");require(f.common.begin_resource_execution_capture().ok,"restart same Common contact capture");check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,boundary,*draft).ok,"old contact boundary cannot cross restart");}
// 原安装可以裁掉未pin的新resolved；只有实际仍在原表的来源才可消费。
void original_trim(bool pin){Fixture f;const auto h=paid_contact(f,false);f.person("observer","A");f.common.state().metadata.player_actor_id="observer";f.common.state().next_instance_id=1000;InteractionState state;for(int i=0;i<128;++i){EncounterRecord e;e.id="encounter:"+std::to_string(2000+i);e.status="resolved";e.created_tick=f.common.tick()+1;e.resolved_tick=e.created_tick;state.encounters.push_back(e);}std::optional<TravelContactTruncationDraft> draft;std::vector<StableId> retained;auto op=installation(h);op.apply_motion=[&](const StableId& id,bool active){auto status=apply_contact_truncation(f.common,f.travel,h,id,active,&draft);if(status.ok&&pin)retained.push_back(id);return status;};require(f.common.begin_resource_execution_capture().ok,"trim original capture");auto b=capture_private_shop_travel_contact_boundary(f.common,f.travel,state,h,op);require(b.ok,"trim original boundary");auto installed=install_encounter(f.common,state,f.common.state().metadata.player_actor_id,op,retained);require(installed.ok&&draft.has_value(),"original trim installation");check(read_private_shop_travel_contact_installation(f.common,f.travel,state,b.value,*draft).ok==pin,"source exists only when same-call retention kept actual record");}
// callback原首错不产生成功来源，Common真实保存点仍负责恢复分配和已动位置。
void failed_callback(){Fixture f;const auto h=paid_contact(f,false);InteractionState state;const auto travel_before=f.travel;const auto common_before=encode_common_state(f.common.state());require(f.common.begin_resource_execution_capture().ok,"failed callback capture");auto save=f.common.begin_savepoint();require(save.ok,"original callback savepoint");auto op=installation(h);std::optional<TravelContactTruncationDraft> draft;op.apply_motion=[&](const StableId& id,bool active){auto s=apply_contact_truncation(f.common,f.travel,h,id,active,&draft);return s.ok?common_failure("ContactCallbackRefused"):s;};auto b=capture_private_shop_travel_contact_boundary(f.common,f.travel,state,h,op);require(b.ok,"failed callback original boundary");auto result=install_encounter(f.common,state,f.common.state().metadata.player_actor_id,op);check(!result.ok&&draft.has_value()&&state.encounters.empty(),"original callback failure has no installed source");check(!read_private_shop_travel_contact_installation(f.common,f.travel,state,b.value,*draft).ok,"successful motion alone is not installed encounter");require(f.common.rollback_savepoint(save.value).ok,"original Common callback rollback");f.travel=travel_before;check(compare_boundary(common_before,encode_common_state(f.common.state())).exact(),"late callback failure exact original Common rollback");}
}
int main(){try{actual_contact(false,true);actual_contact(false,false);actual_contact(true,true);actual_contact(true,false);original_trim(false);original_trim(true);failed_callback();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_CONTACT_SOURCE_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
